import{_ as d,a as e,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","frontmatter":{"title":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","splitFrom":"systems/linux/common-commands.md","showdocs":{"topics":[{"id":"linux","title":"Linux","link":"/topics/linux/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"命令与系统观察","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Linux 常用命令：用途、参数与操作边界","summary":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","status":"active","related":[{"title":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · Linux 基础命令","link":"/systems/linux/common-commands-part-01","kind":"命令与系统观察","scope":"general","audience":"general"}],"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06"}},"headers":[],"relativePath":"systems/linux/common-commands-part-05.md","filePath":"systems/linux/common-commands-part-05.md"}'),a={name:"systems/linux/common-commands-part-05.md"};function c(i,t,n,s,l,m){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="linux-常用命令-用途、参数与操作边界-·-账号、权限与属性至磁盘容量与挂载" tabindex="-1">Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载 <a class="header-anchor" href="#linux-常用命令-用途、参数与操作边界-·-账号、权限与属性至磁盘容量与挂载" aria-label="Permalink to &quot;Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载&quot;">​</a></h1><p><a href="/systems/linux/common-commands">返回分篇目录</a></p><p>先按任务进入主速查；需要理解参数时再展开后面的逐条解释。命令未执行，平台与权限按相应条目核对。</p><h2 id="part-2-账号、权限与属性" tabindex="-1">账号、权限与属性 <a class="header-anchor" href="#part-2-账号、权限与属性" aria-label="Permalink to &quot;账号、权限与属性 {#part-2-账号、权限与属性}&quot;">​</a></h2><h3 id="part-2-用户与组" tabindex="-1">用户与组 <a class="header-anchor" href="#part-2-用户与组" aria-label="Permalink to &quot;用户与组 {#part-2-用户与组}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>groupadd group_name</code></td><td>创建一个新用户组</td></tr><tr><td><code>groupdel group_name</code></td><td>删除一个用户组</td></tr><tr><td><code>groupmod -n new_group_name old_group_name</code></td><td>重命名一个用户组</td></tr><tr><td><code>useradd -c &quot;Name Surname &quot; -g admin -d /home/user1 -s /bin/bash user1</code></td><td>创建一个属于 &quot;admin&quot; 用户组的用户</td></tr><tr><td><code>useradd user1</code></td><td>创建一个新用户</td></tr><tr><td><code>userdel -r user1</code></td><td>删除用户及其主目录等关联内容；先确认数据留存</td></tr><tr><td><code>usermod -c &quot;User FTP&quot; -g system -d /ftp/user1 -s /bin/nologin user1</code></td><td>修改用户属性</td></tr><tr><td><code>passwd</code></td><td>修改口令</td></tr><tr><td><code>passwd user1</code></td><td>修改一个用户的口令 (只允许root执行)</td></tr><tr><td><code>chage -E 2005-12-31 user1</code></td><td>设置用户口令的失效期限</td></tr><tr><td><code>pwck</code></td><td>检查 &#39;/etc/passwd&#39; 的文件格式和语法修正以及存在的用户</td></tr><tr><td><code>grpck</code></td><td>检查组文件的一致性</td></tr><tr><td><code>newgrp group_name</code></td><td>登陆进一个新的群组以改变新创建文件的预设群组</td></tr></tbody></table><p><code>userdel -r</code> 会删除主目录和邮件目录，详见 <a href="https://manpages.debian.org/bookworm/passwd/userdel.8.en.html" target="_blank" rel="noopener noreferrer">userdel 手册</a>。</p><h3 id="part-2-所有者和访问权限" tabindex="-1">所有者和访问权限 <a class="header-anchor" href="#part-2-所有者和访问权限" aria-label="Permalink to &quot;所有者和访问权限 {#part-2-所有者和访问权限}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>ls -lh</code></td><td>显示权限</td></tr><tr><td><code>ls /tmp | pr -T5 -W$COLUMNS</code></td><td>将终端划分成5栏显示</td></tr><tr><td><code>chmod ugo+rwx directory1</code></td><td>设置目录的所有人(u)、群组(g)以及其他人(o)以读（r ）、写(w)和执行(x)的权限</td></tr><tr><td><code>chmod go-rwx directory1</code></td><td>删除群组(g)与其他人(o)对目录的读写执行权限</td></tr><tr><td><code>chown user1 file1</code></td><td>改变一个文件的所有人属性</td></tr><tr><td><code>chown -R user1 directory1</code></td><td>改变一个目录的所有人属性并同时改变改目录下所有文件的属性</td></tr><tr><td><code>chgrp group1 file1</code></td><td>改变文件的群组</td></tr><tr><td><code>chown user1:group1 file1</code></td><td>改变一个文件的所有人和群组属性</td></tr><tr><td><code>find / -perm -u+s</code></td><td>罗列一个系统中所有使用了SUID控制的文件</td></tr><tr><td><code>chmod u+s /bin/file1</code></td><td>设置一个二进制文件的 SUID 位 - 运行该文件的用户也被赋予和所有者同样的权限</td></tr><tr><td><code>chmod u-s /bin/file1</code></td><td>禁用一个二进制文件的 SUID位</td></tr><tr><td><code>chmod g+s /home/public</code></td><td>设置目录 SGID 位，使新建文件继承该目录的组</td></tr><tr><td><code>chmod g-s /home/public</code></td><td>禁用一个目录的 SGID 位</td></tr><tr><td><code>chmod o+t /home/public</code></td><td>设置目录 Sticky 位，限制其中条目的删除和重命名</td></tr><tr><td><code>chmod o-t /home/public</code></td><td>禁用一个目录的 STIKY 位</td></tr></tbody></table><h3 id="part-2-文件系统特殊属性" tabindex="-1">文件系统特殊属性 <a class="header-anchor" href="#part-2-文件系统特殊属性" aria-label="Permalink to &quot;文件系统特殊属性 {#part-2-文件系统特殊属性}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>chattr +a file1</code></td><td>只允许以追加方式读写文件</td></tr><tr><td><code>chattr +c file1</code></td><td>压缩属性，是否支持取决于文件系统</td></tr><tr><td><code>chattr +d file1</code></td><td>在进行文件系统备份时，dump程序将忽略这个文件</td></tr><tr><td><code>chattr +i file1</code></td><td>设置成不可变的文件，不能被删除、修改、重命名或者链接</td></tr><tr><td><code>chattr +S file1</code></td><td>一旦应用程序对这个文件执行了写操作，使系统立刻把修改的结果写到磁盘</td></tr><tr><td><code>lsattr</code></td><td>显示特殊的属性</td></tr></tbody></table><p><a href="https://manpages.debian.org/bookworm/e2fsprogs/chattr.1.en.html" target="_blank" rel="noopener noreferrer">chattr 手册</a>说明属性支持受文件系统限制；不把原 <code>chattr +s/+u</code> 简述当作可靠擦除或删除后恢复保证。</p><h2 id="part-2-打包与压缩" tabindex="-1">打包与压缩 <a class="header-anchor" href="#part-2-打包与压缩" aria-label="Permalink to &quot;打包与压缩 {#part-2-打包与压缩}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>bunzip2 file1.bz2</code></td><td>解压一个叫做 &#39;file1.bz2&#39;的文件</td></tr><tr><td><code>bzip2 file1</code></td><td>压缩一个叫做 &#39;file1&#39; 的文件</td></tr><tr><td><code>gunzip file1.gz</code></td><td>解压一个叫做 &#39;file1.gz&#39;的文件</td></tr><tr><td><code>gzip file1</code></td><td>压缩一个叫做 &#39;file1&#39;的文件</td></tr><tr><td><code>gzip -9 file1</code></td><td>最大程度压缩</td></tr><tr><td><code>rar a file1.rar file1 file2 dir1</code></td><td>同时压缩 &#39;file1&#39;, &#39;file2&#39; 以及目录 &#39;dir1&#39;</td></tr><tr><td><code>unrar x file1.rar</code></td><td>解压rar包</td></tr><tr><td><code>tar -cvf archive.tar file1 file2 dir1</code></td><td>创建一个包含了 &#39;file1&#39;, &#39;file2&#39; 以及 &#39;dir1&#39;的档案文件</td></tr><tr><td><code>tar -tf archive.tar</code></td><td>显示一个包中的内容</td></tr><tr><td><code>tar -xvf archive.tar</code></td><td>释放一个包</td></tr><tr><td><code>tar -xvf archive.tar -C /tmp</code></td><td>将压缩包释放到 /tmp目录下</td></tr><tr><td><code>tar -cvfj archive.tar.bz2 dir1</code></td><td>创建一个bzip2格式的压缩包</td></tr><tr><td><code>tar -jxvf archive.tar.bz2</code></td><td>解压一个bzip2格式的压缩包</td></tr><tr><td><code>tar -cvfz archive.tar.gz dir1</code></td><td>创建一个gzip格式的压缩包</td></tr><tr><td><code>tar -zxvf archive.tar.gz</code></td><td>解压一个gzip格式的压缩包</td></tr><tr><td><code>zip file1.zip file1</code></td><td>创建一个zip格式的压缩包</td></tr><tr><td><code>zip -r file1.zip file1 file2 dir1</code></td><td>将几个文件和目录同时压缩成一个zip格式的压缩包</td></tr><tr><td><code>unzip file1.zip</code></td><td>解压一个zip格式压缩包</td></tr></tbody></table><p>只压缩单文件的 gzip/bzip2 与能归档多个文件/目录的 tar/zip/rar 用途不同；创建 tar 和 rar 时以多文件场景覆盖原单文件重复例。解包前先检查成员与目标目录。</p><h2 id="part-2-磁盘容量与挂载" tabindex="-1">磁盘容量与挂载 <a class="header-anchor" href="#part-2-磁盘容量与挂载" aria-label="Permalink to &quot;磁盘容量与挂载 {#part-2-磁盘容量与挂载}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>df -h</code></td><td>显示已经挂载的分区列表</td></tr><tr><td><code>ls -lSr |more</code></td><td>以尺寸大小排列文件和目录</td></tr><tr><td><code>du -sh dir1</code></td><td>估算目录 &#39;dir1&#39; 已经使用的磁盘空间&#39;</td></tr><tr><td><code>du -sk * | sort -rn</code></td><td>以容量大小为依据依次显示文件和目录的大小</td></tr><tr><td><code>rpm -q -a --qf &#39;%10{SIZE}t%{NAME}n&#39; | sort -k1,1n</code></td><td>以大小为依据依次显示已安装的rpm包所使用的空间 (fedora, redhat类系统)</td></tr><tr><td><code>dpkg-query -W -f=&#39;${Installed-Size;10}t${Package}n&#39; | sort -k1,1n</code></td><td>以大小为依据显示已安装的deb包所使用的空间 (ubuntu, debian类系统)</td></tr></tbody></table><h3 id="part-2-挂载和卸载" tabindex="-1">挂载和卸载 <a class="header-anchor" href="#part-2-挂载和卸载" aria-label="Permalink to &quot;挂载和卸载 {#part-2-挂载和卸载}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>mount /dev/hda2 /mnt/hda2</code></td><td>挂载一个叫做hda2的盘 - 确定目录 &#39;/ mnt/hda2&#39; 已经存在</td></tr><tr><td><code>umount /dev/hda2</code></td><td>卸载一个叫做hda2的盘 - 先从挂载点 &#39;/ mnt/hda2&#39; 退出</td></tr><tr><td><code>umount -n /mnt/hda2</code></td><td>运行卸载操作而不写入 /etc/mtab 文件- 当文件为只读或当磁盘写满时非常有用</td></tr><tr><td><code>mount /dev/fd0 /mnt/floppy</code></td><td>挂载一个软盘</td></tr><tr><td><code>mount /dev/cdrom /mnt/cdrom</code></td><td>挂载一个cdrom或dvdrom</td></tr><tr><td><code>mount /dev/hdc /mnt/cdrecorder</code></td><td>挂载一个cdrw或dvdrom</td></tr><tr><td><code>mount /dev/hdb /mnt/cdrecorder</code></td><td>挂载一个cdrw或dvdrom</td></tr><tr><td><code>mount -o loop file.iso /mnt/cdrom</code></td><td>挂载一个文件或ISO镜像文件</td></tr><tr><td><code>mount -t vfat /dev/hda5 /mnt/hda5</code></td><td>挂载一个Windows FAT32文件系统</td></tr><tr><td><code>mount /dev/sda1 /mnt/usbdisk</code></td><td>挂载一个usb 捷盘或闪存设备</td></tr><tr><td><code>mount -t smbfs -o username=user,password=pass //WinClient/share /mnt/share</code></td><td>挂载一个windows网络共享</td></tr></tbody></table><p>设备和文件系统类型属于来源时代的例子。设备繁忙时先定位占用者；原 <code>user -km</code> 不是可用的卸载说明，已移除。网络共享例含密码占位符，实际凭据不要写进可分享的命令历史。</p>',20)])])}const p=d(a,[["render",c]]);export{u as __pageData,p as default};
